public class Element_hasClass_TriageGen0Test {

    @Test
    public void testHasClass_ExactMatch() {
        Element element = new Element("div");
        element.attr("class", "foo");
        assertTrue("Should return true for exact match", element.hasClass("foo"));
        assertTrue("Should be case-insensitive", element.hasClass("FOO"));
    }

    @Test
    public void testHasClass_EmptyAttribute() {
        Element element = new Element("div");
        element.attr("class", "");
        assertFalse("Should return false for empty class attribute", element.hasClass("foo"));
    }

    @Test
    public void testHasClass_RequestedLongerThanAttribute() {
        Element element = new Element("div");
        element.attr("class", "fo");
        assertFalse("Should return false if requested class is longer than attribute", element.hasClass("foo"));
    }

    @Test
    public void testHasClass_MultipleClasses_First() {
        Element element = new Element("div");
        element.attr("class", "foo bar baz");
        assertTrue("Should find the first class", element.hasClass("foo"));
        assertTrue("Should find the first class case-insensitive", element.hasClass("FOO"));
    }

    @Test
    public void testHasClass_MultipleClasses_Middle() {
        Element element = new Element("div");
        element.attr("class", "foo bar baz");
        assertTrue("Should find the middle class", element.hasClass("bar"));
    }

    @Test
    public void testHasClass_MultipleClasses_Last() {
        Element element = new Element("div");
        element.attr("class", "foo bar baz");
        assertTrue("Should find the last class", element.hasClass("baz"));
    }

    @Test
    public void testHasClass_MultipleClasses_WithExtraWhitespace() {
        Element element = new Element("div");
        element.attr("class", "  foo   bar  ");
        assertTrue("Should handle leading whitespace", element.hasClass("foo"));
        assertTrue("Should handle multiple spaces between classes", element.hasClass("bar"));
        assertTrue("Should handle trailing whitespace", element.hasClass("bar"));
    }

    @Test
    public void testHasClass_PartialMatchFails() {
        Element element = new Element("div");
        element.attr("class", "foobar baz");
        assertFalse("Should not match if it's just a substring of a class", element.hasClass("foo"));

        element.attr("class", "foo barbaz");
        assertFalse("Should not match if it's a prefix of a class", element.hasClass("bar"));
    }

    @Test
    public void testHasClass_Mismatch() {
        Element element = new Element("div");
        element.attr("class", "foo bar");
        assertFalse("Should return false if class not present", element.hasClass("missing"));
    }

    @Test
    public void testHasClass_WhitespaceOnly() {
        Element element = new Element("div");
        element.attr("class", "   ");
        assertFalse("Should return false for whitespace only", element.hasClass("foo"));
    }

    @Test
    public void testHasClass_DifferentLengthsButNotMatch() {
        Element element = new Element("div");
        element.attr("class", "foo bar");
        // len (7) > wantLen (3)
        assertFalse("Should return false when lengths differ but content doesn't match", element.hasClass("abc"));
    }
}
